'use strict';
// L10-J: the SVG import adapter against the baseline `importSVGString` oracle (tests/fixtures/native-import-adapters/svg-flows.json,
// generated by tools/gen_svg.mjs from fbe4b8a3 on the shipped Paper.js), through the REAL native-import-core.js and the REAL contract.
const test = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const svg = require('../src/js/adapters/native-import-svg.js');
const coreModule = require('../src/js/adapters/native-import-core.js');
const contract = require('../src/js/adapters/native-import-contract.js');
const helper = require('./helpers/native-import-paper.cjs');
const { makeSession, makePorts, layerRow } = require('./helpers/native-import-session.cjs');

const FIX = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'native-import-adapters', 'svg-flows.json'), 'utf8'));
const paper = helper.load();
const ADAPTER = path.join(__dirname, '..', 'src', 'js', 'adapters', 'native-import-svg.js');
const BIG = 1 << 20; // oracle replay only: the default 4096-byte bound is exercised by its own tests below

function run(flow, adapterModule, extra) {
  const rows = { ok: [layerRow('L0', 'Layer 1')], locked: [layerRow('L0', 'Layer 1', { locked: true })], none: [layerRow('L0', 'Layer 1')] }[flow.layer];
  const h = makeSession({ layers: rows });
  const { ports } = makePorts(h, Object.assign({ maxRequestBytes: BIG }, extra));
  const toasts = [];
  const root = flow.parse === 'ok' ? helper.mkNode(paper, flow.tree) : null;
  assert.equal(root ? helper.treeTok(paper, root) : 'fail', flow.treeTok, `${flow.name}: the materialised tree is the one the generator ran`);
  const asked = [];
  const adapter = adapterModule.create({
    paper: helper.port(paper, (text, options) => { asked.push([text, options]); if (flow.parse === 'throw') throw new Error('bad svg'); return root; }),
    core: coreModule.create(ports),
    activeLayerUid: () => (flow.layer === 'none' ? 'gone' : 'L0'),
    t: (key) => FIX.templates[flow.locale][key], notify: (m) => toasts.push(m),
  });
  return adapter.importText('<svg/>', { noFit: flow.noFit }).then((result) => ({ result, toasts, h, asked }));
}
const sameJson = (a, b) => JSON.stringify(a) === JSON.stringify(b);

test('fixture pins the baseline commit, the shipped Paper.js and its row counts', () => {
  const paperText = fs.readFileSync(path.join(__dirname, '..', 'src', 'paper-full.min.js'));
  assert.equal(FIX.meta.baseline, 'fbe4b8a33e6d5a229f014154df2ba21988a9fabc');
  assert.equal(FIX.meta.sources['paper-full.min.js'], crypto.createHash('sha256').update(paperText).digest('hex'));
  assert.equal(FIX.flows.length, 59);
  const by = {};
  FIX.flows.forEach((f) => { by[f.expect.outcome] = (by[f.expect.outcome] || 0) + 1; });
  assert.deepEqual(by, { imported: 39, empty: 8, refused: 7, parse_failed: 5 });
  assert.equal(FIX.flows.reduce((n, f) => n + f.expect.records.length, 0), 62);
  assert.equal(FIX.flows.reduce((n, f) => n + f.expect.skipped.length, 0), 27);
  assert.deepEqual(FIX.flows.filter((f) => f.expect.refusal).map((f) => f.name), ['degenerate-point']);
});

test('every baseline flow is reproduced: toasts, count, records, source ids and skip reports', async () => {
  let imported = 0;
  for (const flow of FIX.flows) {
    const { result, toasts, h, asked } = await run(flow, svg);
    const e = flow.expect;
    if (flow.parse !== 'ok') assert.deepEqual(asked.map((a) => a[1]), [{ insert: false, expandShapes: true }], flow.name);
    assert.deepEqual(toasts, e.refusal ? [] : e.toasts, `${flow.name}: toasts`);
    if (e.outcome !== 'imported') {
      assert.equal(h.calls.length, 0, `${flow.name}: nothing is dispatched`);
      assert.equal(result.status, { parse_failed: 'nothing', empty: 'nothing', refused: 'refused' }[e.outcome], flow.name);
      continue;
    }
    if (e.refusal) {
      assert.equal(result.status, 'invalid', flow.name);
      assert.equal(result.reason, e.refusal.reason);
      assert.equal(result.detail.sourceId, e.refusal.sourceId);
      assert.equal(h.calls.length, 0);
      continue;
    }
    imported += 1;
    assert.equal(h.calls.length, 1, `${flow.name}: ONE dispatch for the whole import`);
    const sent = h.calls[0];
    assert.equal(sent.command, 'object.import.batch');
    assert.deepEqual(sent.layers, []);
    assert.ok(sameJson(sent.records, e.records), `${flow.name}: records equal the baseline serializer mapping`);
    assert.deepEqual(sent.skipped, e.skipped, `${flow.name}: skipped`);
    assert.deepEqual(sent.unavailable, []);
    assert.equal(result.status, 'imported');
    assert.equal(result.count, e.ret, `${flow.name}: the baseline return value`);
    assert.equal(result.applied, e.records.length > 0, `${flow.name}: a batch with no record is a no-op`);
    assert.equal(h.state.contentRevision, e.records.length > 0 ? 8 : 7);
    assert.equal(result.objects.length, e.records.length);
    assert.deepEqual(result.skipped, e.skipped);
    assert.doesNotThrow(() => contract.payload(contract.OP, sent), flow.name);
  }
  assert.equal(imported, 38);
});

test('a hole no exterior claims and an unsupported element are typed skips, never silently dropped', async () => {
  const flow = (name) => FIX.flows.find((f) => f.name === name);
  const holes = await run(flow('all-ccw-compound'), svg);
  assert.deepEqual(holes.h.calls[0].records, []);
  assert.deepEqual(holes.h.calls[0].skipped.map((s) => s.reason), ['unclaimed-hole', 'unclaimed-hole']);
  assert.equal(holes.result.applied, false, 'no record: presence, bytes and history are untouched');
  assert.equal(holes.h.state.contentRevision, 7);
  const mix = await run(flow('skipped-mix'), svg);
  assert.deepEqual(mix.h.calls[0].skipped.map((s) => s.sourceId), ['svg:0:2', 'svg:0:3', 'svg:0:5', 'svg:0:6', 'svg:0:7']);
  assert.deepEqual(mix.result.items[0].skippedClasses, ['PointText', 'Group', 'PointText', 'Group', 'PointText']);
});

test('records carry exactly what the baseline serializer persisted: rounding, white stroke fallback, caps, dashes, alpha', async () => {
  const one = await run(FIX.flows.find((f) => f.name === 'open-dashed-line'), svg);
  const rec = one.h.calls[0].records[0].record;
  assert.deepEqual(rec.vector, { stroke: { kind: 'solid', r: 0.2, g: 0.4, b: 0.6, a: 1 }, hasRealStroke: true, strokeWidth: 4, strokeCap: 'butt', strokeJoin: 'miter', miterLimit: 10, dashArray: [4, 2], dashOffset: 1.5, opacity: 1 });
  assert.equal(rec.fill, null);
  const strokeless = await run(FIX.flows.find((f) => f.name === 'strokeless-fill'), svg);
  assert.equal(strokeless.h.calls[0].records[0].record.vector.stroke, null, 'the #ffffff serializer fallback is not a stroke');
  assert.equal(strokeless.h.calls[0].records[0].record.vector.hasRealStroke, false);
  const white = await run(FIX.flows.find((f) => f.name === 'white-stroke'), svg);
  assert.deepEqual(white.h.calls[0].records[0].record.vector.stroke, { kind: 'solid', r: 1, g: 1, b: 1, a: 1 }, 'a real white stroke stays a stroke');
  const alpha = await run(FIX.flows.find((f) => f.name === 'plain-one'), svg);
  assert.equal(alpha.h.calls[0].records[0].record.fill.a, 128 / 255, 'a #rrggbb80 fill keeps its byte/255 alpha');
  assert.equal(svg.r3(1.2345), 1.235);
  assert.equal(svg.r3(-0.0004) === 0, true);
  assert.equal(Object.is(svg.r3(-0.0004), -0), true, 'Math.round keeps -0 (JSON.stringify prints 0, as serP stored it)');
  assert.equal(JSON.stringify(svg.r3(-0.0004)), '0');
  assert.equal(svg.r3(NaN), 0);
});

test('a paint that is not #rrggbb[aa] (a gradient prints or throws) refuses the whole import with the offending source id', async () => {
  for (const printer of [() => { throw new Error('gradient'); }, () => 'url(#g)', () => 'rgba(1,2,3,0.5)']) {
    const tree = helper.mkNode(paper, FIX.flows.find((f) => f.name === 'plain-one').tree);
    const leaf = tree.children[0];
    const realClone = leaf.clone;
    leaf.clone = function (options) { // the adapter bakes a clone: that clone carries the unprintable paint
      const copy = realClone.call(this, options);
      Object.defineProperty(copy, 'fillColor', { configurable: true, get: () => ({ alpha: 1, toCSS: printer }) });
      return copy;
    };
    const h = makeSession();
    const adapter = svg.create({ paper: helper.port(paper, () => tree), core: coreModule.create(makePorts(h, { maxRequestBytes: BIG }).ports), activeLayerUid: () => 'L0', t: (k) => FIX.templates.en[k], notify() {} });
    const out = await adapter.importText('<svg/>');
    assert.deepEqual([out.status, out.reason, out.detail.sourceId], ['invalid', 'unsupported_paint', 'svg:0:1:0']);
    assert.equal(h.calls.length, 0);
  }
});

test('a path with more than 256 anchors (or fewer than 2) is refused locally with segment_count and nothing is sent', async () => {
  const base = FIX.flows.find((f) => f.name === 'plain-one').tree;
  const withAnchors = (count) => {
    const tree = JSON.parse(JSON.stringify(base));
    tree.children[0].segs = Array.from({ length: count }, (_, i) => [i, i % 7, 0, 0, 0, 0]);
    return tree;
  };
  for (const [count, ok] of [[256, true], [257, false], [1, false]]) {
    const h = makeSession();
    const adapter = svg.create({ paper: helper.port(paper, () => helper.mkNode(paper, withAnchors(count))), core: coreModule.create(makePorts(h, { maxRequestBytes: BIG }).ports),
      activeLayerUid: () => 'L0', t: (k) => FIX.templates.en[k], notify() {} });
    const out = await adapter.importText('<svg/>');
    if (ok) { assert.equal(out.status, 'imported', `${count} anchors`); assert.equal(h.calls.length, 1); continue; }
    assert.deepEqual([out.status, out.reason, out.detail.count], ['invalid', 'segment_count', count], `${count} anchors`);
    assert.equal(h.calls.length, 0);
  }
});

test('the default 4096-byte request bound refuses a large import before any dispatch and admits a small one', async () => {
  const big = FIX.flows.find((f) => f.name === 'rand-0');
  const refused = await run(big, svg, { maxRequestBytes: undefined });
  assert.equal(refused.result.status, 'too_large');
  assert.equal(refused.result.limit, 4096);
  assert.ok(refused.result.bytes > 4096);
  assert.equal(refused.h.calls.length, 0);
  assert.deepEqual(refused.toasts, [], 'no success toast for an import that was not published');
  const small = await run(FIX.flows.find((f) => f.name === 'plain-one'), svg, { maxRequestBytes: undefined });
  assert.equal(small.result.status, 'imported');
  assert.equal(small.h.calls.length, 1);
});

test('several files publish once or not at all, with per-file ids and per-file toasts', async () => {
  const a = FIX.flows.find((f) => f.name === 'plain-one'), b = FIX.flows.find((f) => f.name === 'open-dashed-line');
  const h = makeSession();
  const { ports } = makePorts(h, { maxRequestBytes: BIG });
  const trees = [helper.mkNode(paper, a.tree), null, helper.mkNode(paper, b.tree)];
  let n = 0;
  const toasts = [];
  const adapter = svg.create({
    paper: helper.port(paper, () => { const t = trees[n++]; if (!t) throw new Error('bad'); return t; }),
    core: coreModule.create(ports), activeLayerUid: () => 'L0', t: (k) => FIX.templates.en[k], notify: (m) => toasts.push(m),
  });
  const result = await adapter.importTexts([{ text: 'a' }, { text: 'broken' }, { text: 'b' }]);
  assert.equal(result.status, 'imported');
  assert.equal(h.calls.length, 1, 'ONE dispatch');
  assert.deepEqual(h.calls[0].records.map((r) => r.sourceId), ['svg:0:1:0', 'svg:2:1:0']);
  assert.deepEqual(result.items.map((i) => i.outcome), ['imported', 'parse_failed', 'imported']);
  assert.deepEqual(toasts, [FIX.templates.en.toastSvgImportFailed, '1 vector shape(s) imported', '1 vector shape(s) imported']);
  assert.equal(h.state.contentRevision, 8, 'one revision for both files');
  // A native refusal publishes neither file and toasts no success.
  const h2 = makeSession({ fault: 'busy' });
  const toasts2 = [];
  const t2 = [helper.mkNode(paper, a.tree), helper.mkNode(paper, b.tree)];
  let m = 0;
  const refusedRun = await svg.create({ paper: helper.port(paper, () => t2[m++]), core: coreModule.create(makePorts(h2, { maxRequestBytes: BIG }).ports), activeLayerUid: () => 'L0', t: (k) => FIX.templates.en[k], notify: (x) => toasts2.push(x) })
    .importTexts([{ text: 'a' }, { text: 'b' }]);
  assert.equal(refusedRun.status, 'refused');
  assert.deepEqual(toasts2, []);
  assert.equal(h2.state.contentRevision, 7);
});

test('file, paste and menu entries read through ports and never touch a legacy importer', async () => {
  const flow = FIX.flows.find((f) => f.name === 'plain-one');
  const h = makeSession();
  const { ports } = makePorts(h, { maxRequestBytes: BIG });
  const read = [];
  const files = [{ name: 'a.svg', type: '' }, { name: 'b.png', type: 'image/png' }, { name: 'c', type: 'image/svg+xml' }];
  const make = () => svg.create({
    paper: helper.port(paper, () => helper.mkNode(paper, flow.tree)), core: coreModule.create(ports), activeLayerUid: () => 'L0',
    t: (k) => FIX.templates.en[k], notify() {}, readText: async (f) => { read.push(f.name); return '<svg/>'; },
    pickFile: async () => ({ name: 'p.svg', text: '<svg/>' }),
  });
  const imported = await make().importFiles(files);
  assert.deepEqual(read, ['a.svg', 'c'], 'only SVG files are read (name suffix or MIME), in order');
  assert.deepEqual(h.calls[0].records.map((r) => r.sourceId), ['svg:0:1:0', 'svg:1:1:0']);
  assert.equal(imported.status, 'imported');
  assert.equal((await make().openFile()).status, 'imported');
  const cancelled = svg.create({ paper: helper.port(paper, () => null), core: coreModule.create(ports), activeLayerUid: () => 'L0', t() {}, pickFile: async () => null });
  assert.deepEqual(await cancelled.openFile(), { status: 'cancelled' });
  assert.equal(svg.isSvgFile({ name: 'X.SVG', type: '' }), true);
  assert.equal(svg.isSvgFile({ name: 'x.svg ', type: '' }), false);
  assert.equal(svg.isSvgFile(null), false);
});

test('without a presented native session or a declared import the adapter is typed unavailable and parses nothing', async () => {
  const flow = FIX.flows.find((f) => f.name === 'plain-one');
  let parsed = 0;
  const mk = (h, over) => svg.create({ paper: helper.port(paper, () => { parsed += 1; return helper.mkNode(paper, flow.tree); }), core: coreModule.create(makePorts(h, over).ports), activeLayerUid: () => 'L0', t: (k) => FIX.templates.en[k], notify() {} });
  const undeclared = makeSession({ declared: false });
  assert.deepEqual(await mk(undeclared).importText('x'), { status: 'unavailable', reason: 'native_declaration_absent', items: [] });
  const unpresented = makeSession();
  assert.equal((await mk(unpresented, { available: () => false }).importText('x')).reason, 'no_presented_native_session');
  assert.equal((await mk(unpresented, { currentSession: () => null }).importText('x')).status, 'unavailable');
  assert.equal(parsed, 0);
});

// ---- negative controls: one edit of the ADAPTER source each; the oracle replay must catch every one ----
function mutant(edits) {
  let source = fs.readFileSync(ADAPTER, 'utf8');
  for (const [from, to] of edits) {
    assert.equal(source.split(from).length, 2, `mutation anchor must occur exactly once: ${from}`);
    source = source.replace(from, to);
  }
  const m = { exports: {} };
  new Function('module', 'exports', source)(m, m.exports);
  return m.exports;
}
async function mismatches(adapterModule) {
  let bad = 0;
  for (const flow of FIX.flows) {
    if (flow.expect.outcome !== 'imported' || flow.expect.refusal) continue;
    try {
      const { h } = await run(flow, adapterModule);
      if (!h.calls.length || !sameJson(h.calls[0].records, flow.expect.records) || !sameJson(h.calls[0].skipped, flow.expect.skipped)) bad += 1;
    } catch (_) { bad += 1; }
  }
  return bad;
}
test('controls: the unmutated adapter has no mismatch and every source mutation is caught by the oracle replay', async () => {
  assert.equal(await mismatches(svg), 0);
  const mutants = [
    ['exterior/hole rule swapped', [['const exteriors = children.filter((c) => c.clockwise);', 'const exteriors = children.filter((c) => !c.clockwise);'], ['const holes = children.filter((c) => !c.clockwise);', 'const holes = children.filter((c) => c.clockwise);']]],
    ['island style not carried', [['isl.fillColor = fillColor; isl.strokeColor = strokeColor; isl.strokeWidth = strokeWidth; isl.opacity = opacity;', 'isl.fillColor = fillColor;']]],
    ['merged style not carried', [['merged.fillColor = fillColor; merged.strokeColor = strokeColor; merged.strokeWidth = strokeWidth; merged.opacity = opacity;', 'merged.fillColor = fillColor;']]],
    ['hole containment test dropped', [['const mine = holes.filter((h) => ext.bounds.contains(h.bounds));', 'const mine = holes;']]],
    ['seam revisit dropped', [['out.push(extSegs[pair.i]); // back out', 'void 0; // back out']]],
    ['world matrix not baked', [['clone.transform(worldMatrix(P, leaf.item));', 'void 0;']]],
    ['fit scale ignored', [['c.scale(s, b.center);', 'void 0;']]],
    ['recentring ignored', [['c.translate(targetCx - b.center.x, targetCy - b.center.y);', 'void 0;']]],
    ['rounding to three decimals dropped', [['function r3(v) { return isFinite(v) ? Math.round(v * 1000) / 1000 : 0; }', 'function r3(v) { return isFinite(v) ? v : 0; }']]],
    ['strokeless fallback taken as a stroke', [['hasRealStroke: !!p.strokeColor,', 'hasRealStroke: true,']]],
    ['unsupported elements dropped from the report', [['parsed.skipped.forEach((row) => skipped.push(', 'parsed.skipped.slice(0, 0).forEach((row) => skipped.push(']]],
    ['unclaimed holes dropped from the report', [['out.unclaimed.forEach((child) => skipped.push(', 'out.unclaimed.slice(0, 0).forEach((child) => skipped.push(']]],
    ['source ids keyed by output position', [['records.push({ sourceId: `${prefix}:${leaf.index}:${ordinal}`,', 'records.push({ sourceId: `${prefix}:${ordinal}`,']]],
  ];
  for (const [name, edits] of mutants) assert.ok(await mismatches(mutant(edits)) > 0, `mutation not caught: ${name}`);
});
